import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集说卷一","description":"周易集说 - 周易集说卷一","frontmatter":{"title":"周易集说卷一","description":"周易集说 - 周易集说卷一"},"headers":[],"relativePath":"zh/classics/jishuo/002.md","filePath":"zh/classics/jishuo/002.md"}'),r={name:"zh/classics/jishuo/002.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集说卷一" tabindex="-1">周易集说卷一 <a class="header-anchor" href="#周易集说卷一" aria-label="Permalink to “周易集说卷一”">​</a></h1><p>钦定四库全书</p><p>宋俞琰撰。</p><p>周，代名；易，书名。犹周书题周以别于夏、殷也。易有二义，变易也，交易也。变易者，阳变阴，阴变阳也；交易者，阳交阴，阴交阳也。观先天图，可见经即篇也。孔子称乾坤之策曰「二篇」，则「经」字乃后人所加。吕东莱谓「经分上下，必始于文王」，郭白云谓「序卦已分，其来尚矣」，皆不言分经之由。邵康节曰：「重卦之象，不易者八，反易者二十八，故卦有六十四，而用止乎二百一十有六。」知此，则知经之所以分上下者，盖有由焉，非苟然也。或疑上经卦三十，下经卦三十四，多寡不均。殊不知卦有对体，有覆体。何谓覆体？屯倒转为蒙，需倒转为讼之类是也。何谓对体？乾、坤、坎、离、颐、大过、中孚、小过，相对而不可覆者是也。余皆一卦倒转为两卦，故上经卦三十，约之则十八，下经卦三十四，约之亦十八，谓之不均可乎？卦分内外二体，凡六十四阳、六十四阴，约为三十六，则上经纯阳卦六，纯阴卦四；下经纯阳卦四，纯阴卦六。阴阳相重之卦，上下经皆八，不亦均乎？上经阳爻八十六，阴爻九十四，约为十八，则五十二阳、五十六阴，共一百八。下经阳爻一百六，阴爻九十八，约为十八，则五十六阳、五十二阴，亦一百八。其均如此。孔颖达谓，繋辞分上下，无异义，直以简帙重大，是以分之。晁以道乃曰：「古者竹简重大，分经为二篇。」今又何必以二篇成帙？盖皆不知六十四卦，约之则为两十八也。䷀ 乾下乾上 「乾」：元亨利贞。</p><p>「乾」，健也。画奇属阳而体刚，故其性健。此卦「乾」下「乾」上，而六画之奇，纯乎阳，刚健之至也。「元」，大也。「亨」，通也。「利」，宜也。「贞」，正而固也。其占为始虽大通，又宜固守以正，然后可保其终。盖不可恃其至健而妄动也。初九：潜龙勿用。</p><p>「初」，即一之异名。卦画自下而上，故以一为初。「一」言初，则六为终；「六」言上，则一为下。互文相通也。「九」，阳数。「潜」，藏也。「龙」，大而灵变之物，以象「乾」六爻之变也。「勿」，禁止之辞。「用」，谓动而施为。初九在下「乾」之下，阳气潜藏，故其象为「潜龙」。潜则隐而未见，故其占为君子「勿用」。九二，见龙在田，利见大人。</p><p>「田」，地上也。龙之出见而在田，犹君子出仕而在位也。「大人」，有大德之人也。九二在下「乾」之中，乃阳气发见于地上之时，故其象为「见龙在田」，其占为「利见在下」之「大人」。「见龙」之「见」，音现。「利见」之「见」，如字。</p><p>九三，君子终日乾乾，夕惕若，厉无咎。</p><p>六爻皆君子也。此爻居天田之间，正当人位，故特称「君子」以发之。在下「乾」之终，故曰「终日」。下「乾」终而上「乾」继之，故曰「乾乾」。「夕」，日之过中也。「惕」，惧也。「若」，助语。九三处重乾之交，而自强不息，又因日之过中，省察自己之不中而兢兢焉，故其象如此。「厉」，危而不安也。「咎」，谴责也。夫以九居三，刚而不中，居下之上，乃危地也。其占何以「无咎」？曰：君子「终日乾乾」，至于日之夕而犹惕惧，故虽危厉，亦「无咎」也。「夕惕若」为句，「厉无咎」为句。</p><p>九四，或跃在渊，无咎。</p><p>「或」，疑辞，谓其在两「乾」之间，而或上或下也。「渊」，深水，龙之所居也。九四亦刚而不中者也，离地而跃于人之上，能「无咎」乎？所以「无咎」者，跃而在渊，处卑而不犯上也。「乾」六爻虽皆君德，以位言，则唯五为君，余皆臣也。九四爻刚位柔，以臣近君，以渊近天，故其象占如此。</p><p>九五，飞龙在天，利见大人。</p><p>九五，君位之至尊，犹天之不可阶而升也，故其象为龙之飞而在天，其占为利见在上之大人。上九，亢龙，有悔。亢，口浪反。极甚之为「亢」。上九过中而居「乾」终，六阳之穷，故其象为「亢龙」。「悔」，懊恨也。有过则有悔。上九位高而不知退，动极而不知止，故其占曰「有悔」。</p><p>用九，见群龙无首，吉。</p><p>筮法：阳数穷于九，阴数穷于六，穷则必变。「乾」爻用九，坤爻用六，盖取其变也。「见」，如字。「见群龙无首」为句。「乾」为首，「乾」六爻皆九，则变而为「坤」，是为「群龙无首」之象。「吉」，善也。占者见此象而处后则善，不可为首也。刚太过则折，非善道也，故「上九，亢龙有悔」。六阳变为六阴，则刚而能柔，吉之道也，故</p><p>「用九，见群龙无首，吉」。䷁ 坤下坤上</p><p>「坤」，元亨，利牝马之贞。君子有攸往，先迷，后得主，利。西南得朋，东北丧朋。安贞吉。</p><p>「坤」，顺也。画偶属阴而体柔，故其性顺。此卦「坤」下「坤」上，而六画之偶纯乎阴，柔顺之至也。「坤」顺「乾」之健，故其占亦为「元亨」。北地马群，每十牝随一牡而行，不入它群，是为「牝马之贞」。坤道以阴从阳，其贞如牝马之从牡，则利，故曰「利牝马之贞」。易中凡称君子，皆指占者而言。「有攸往」，谓有所行也。「坤」从「乾」而行，先乎「乾」则迷而失道，后乎「乾」则得「乾」为主而利。故曰「君子有攸往，先迷，后得主，利」。「朋」，坤类也。「西南」，「坤」之本方。「兑」、「离」、「巽」皆「坤」类，是为「得朋」。出而从乾，则东北震、艮、坎非坤类，是为「丧朋」。君子之出处，随寓能安，壹是皆以贞自持，盖无往而不吉，故曰：「西南得朋，东北丧朋，安贞吉。」初六，履霜，坚冰至。</p><p>「六」，阴数。「霜」，阴气之始凝也。坤初而言「履霜坚冰至」，以象小人恶迹，始虽甚微，如霜之在地，盛而与君子为敌，则如冰之坚固也。「至」，谓驯致其道，必至于此极也。</p><p>六二，直方大，不习无不利。</p><p>以六居二，得坤道之正，又在坤道之中。正则无私无曲，中则无偏无党，是以执直而不回，执方而不移也。易以阳为大，阴为小，六二阴小而称大，何也？曰：从乾也。从乾而行，则大也。「习」，与书太甲篇「习与性成」之「习」同。「不习」，谓六二中正，不与初六不中不正之朋相习为不善也。择善而得所从，则不疑其所行，故「无不利」。</p><p>六三，含章可贞，或从王事，无成有终。</p><p>以六居三，阴中有阳，故曰「含章」，谓其有美而不露于外也。「可贞」，谓当其可而贞，非纯乎固执也。「或」，疑辞，谓非必也。「从王事」，谓从乾君之事。坤道固宜静而有守，或有王事，则动而从之，弗违也。「无成」，谓持美以归于君，不居其成功也。「有终」，谓职分居此，则当终其劳也。六三爻柔位刚，而在下体之终，故其象占如此。</p><p>六四，括囊，无咎无誉。</p><p>「咎」，致罪；「誉」，致疑。唯能谨密如囊口之结括，则「无咎无誉」。六四爻位俱柔，而近六五，故其象占如此。六五，黄裳，元吉。</p><p>「黄」，中色；「裳」，下服。「坤」之从乾，犹裳之承衣也。六五柔顺而得中，降尊而处卑，故其象如此，其占为大善之吉。坤六爻皆臣道，「坤」之六五，其位虽君，其道则臣，故不言「黄衣」，而言「黄裳」。盖唯「黄裳」则「元吉」，不「黄裳」则大凶。</p><p>上六，龙战于野，其血玄黄。</p><p>上六居坤终，六阴之穷，阴盛而与阳对敌，故其象为龙之战斗。「野」，外也。在外卦之外，故言「野」。「血」，伤也。「玄黄」者，阴阳之杂也。战而两败俱伤，故曰「其血玄黄」。用六：利永贞。</p><p>筮法体七、八而用九、六者，七、八少不变，九六老则变也。坤六爻俱六，则变而为「乾」本体，盖阴柔也。以其阴柔之动，或失于邪，故戒之曰：「利永贞」。「永」，久也。䷂ 震下坎上</p><p>屯，元亨，利贞。勿用有攸往，利建侯。</p><p>屯，张伦反。此卦下震上坎。「震」，动也。「坎」，险也。动而遇险，则其动艰难，而未能遽通，「屯」之义也。处屯之时，不动则不能出险，动则可以大亨。然动乎险中，则宜固守以正，故其占曰：「元亨，利贞。」盖总上下二体而言处屯之道也。「勿用有攸往」，指上体之坎，谓坎险在前，不可遽往也。「利建侯」，指下体之震，谓宜建立侯国之君也。</p><p>初九：磐桓，利居贞，利建侯。</p><p>磐，大石也，与渐六二之「磐」同。桓，柱也。礼记檀弓篇所谓「桓楹」是也。横渠张子曰：「磐桓，犹言柱石。」或以「磐桓」为盘旋徘徊之义，误矣。「居」，不动也。初九震体好动，故戒之曰：「磐桓，利居贞。」震为长子，以刚德处下，为成卦之主，而有济屯之才，故以彖辞「利建侯」属之。此爻凡两言「利」，当分为两说。春秋左氏传云：「孔成子遇此占，以示史朝。史朝对曰：各以所利。」盖「居贞」自是「居贞」之「利」，「建侯」自是「建侯」之「利」，不可纽为一说也。</p><p>六二，屯如邅如，乘马班如，匪寇，婚媾。女子贞不字，十年乃字。</p><p>邅，张连反，难行不进之貌。「乘」，当依项平庵按陆德明释文作绳证反。四马曰「乘」。班，分布貌，与春秋左氏传「班荆」之「班」同。「如」，助语。六二虽是震体之动，然非动之主，况其才柔弱，岂能济屯？所以「屯如邅如，乘马班如」者，待初九之动而后动也。五，坎体之盗，故言「寇」。与二正应，则「匪寇」矣，乃「婚媾」也。六二阴柔，故称「女子」。曲礼云：「女子许嫁，笄而字。」字以代名也。今曰「女子贞不字」者，以初九近而见逼，故未可字也。「十年乃字」者，十年之后，初既求四为婚媾，则彼自得偶，无复见逼，然后可以字也。婚媾而「十年乃字」，此亦屯道艰难，而未能遽通之义。夫「屯如邅如」、「乘马班如」，自是一说。「匪寇，婚媾，女子贞不字，十年乃字」，又自是一说。易中多有一爻而取两象者，皆当分为两说，混而为一，则凿矣。</p><p>六三，即鹿无虞，惟入于林中。君子几，不如舍，往吝。「即」，就也。「鹿」，指五。「无虞」，谓无应也。书舜典云：「咨益，汝作朕虞。」孔安国云：「掌山泽之官。」周礼有「山虞」。郑玄云：「虞，度也。度知山林之大小及所生者。」「几」，音机，近也。「舍」，武夜反，止也。「几」，谓时位至于六三，则当尽其才力，不可不及也。「舍」，谓职分终于六三，则又当量其才力，不可过也。「吝」，恨惜也。六三才柔而志刚，盖欲往济九五之屯，而上无应援，犹即鹿而无虞人引导，故虽入于林中，不若止而弗往，往则俱陷，徒恨惜也。「君子」，指占者而言。三居下体震动之极，而互艮止，故其象占如此。「惟」，当作「虽」，与丰初九「虽旬无咎」之「虽」同。</p><p>六四：乘马班如，求婚媾，往，吉，无不利。</p><p>六四言「乘马班如」，是亦有志于济屯，而其才不逮者也。初来求四，四往应初，得「婚媾」之正，故「吉」而「无不利」。九五：屯其膏，小贞吉，大贞凶。</p><p>九五正陷于「坎」险之中，而膏泽不下于民，故其象为「屯其膏」。处屯之时，与常时不同，唯能退托不明，而以谦小自守，则「吉」。若以尊大自居，固执而不知变，则「凶」。故其占曰：「小贞吉，大贞凶。」</p><p>上六：乘马班如，泣血涟如。</p><p>二比初，四应初，俱言「乘马班如」，盖皆待其动而后动也。上与初非应非比，亦言「乘马班如」，何所待而然耶？曰：上与三、四皆有济屯之志，而无其才者也。既不能自动，而又居屯之穷，唯有忧惧而「泣血涟如」，故其象如此。其占不言「凶」者，时势使然，非其罪也。䷃ 坎下艮上</p><p>蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞。</p><p>「蒙」，与书伊训「蒙士」之「蒙」同。内险而不自安，外止而不能动，蒙之义也。「亨」以下，占辞也。九二以刚德居中，能启群阴之「蒙」，故蒙有亨通之道焉。「我」，指二。「童蒙」，指五。五，君也，「蒙」之主也。乃主二而称「我」，何也？曰：五在六十四卦中，乃定位之主；二在蒙，乃成卦之主，盖一时得权者也。曲礼云：「礼闻来学，不闻往教。」「蒙」，六五以柔德居中，虚己以求二，非二往求于五，故曰「匪我求童蒙，童蒙求我」。「筮」者，揲蓍叩神以决疑也。「初筮」，指九二。「再三」，指上九。「告」，如字。「三」，去声。「渎」，与少仪「毋渎神」之「渎」同。「不告」，与诗小旻「我龟既厌，不我告犹」之义同。初筮则其志专一，故「告」；再、三则烦渎，故「不告」。盖童蒙之求师，与人之求神，其道一也。「贞」，正也。二、五皆不正，故戒之曰「利贞」。</p><p>初六：发蒙，利用刑人，用说桎梏。以往，吝。「发蒙」，教之于初也。教之弗听，则刑之宜也。若不施鞭扑，遽说其桎梏，纵之使往，必待其罪大恶极而后击之，虽恨惜亦无及矣。「说」，音脱。「桎梏」，刑具。此爻凡两言用，善用之则利，不善用之则吝也。九二，包蒙，吉；纳妇，吉；子克家。</p><p>此爻凡两言「吉」，「包蒙」之「吉」，谓包初六在下者之蒙也。「纳妇」之吉，谓纳六三近比之阴柔也。</p><p>九二刚得中而无过，故为「包蒙」、「纳妇」皆吉。以刚处内，而上与六五之柔相应，故又为「子克家」之象。「克家」，能治其家也。</p><p>六三，勿用取女，见金夫，不有躬，无攸利。</p><p>取，音娶。「金夫」，指九二之刚。六三阴柔，不正不中，不可取也。舍上九之应，而近唯九二之从，此女子见金夫而不有其躬者也。其象如此，故其占为「无攸利」。六四，困蒙，吝。</p><p>六四与九二、上九相远，「困」而不学，是可恨惜也。纯乎阴柔，而乘应亦皆阴柔，故其象占如此。六五，童蒙，吉。</p><p>「蒙」之六五，以阴柔之小而居尊位，此「童蒙」之君也。能下求九二刚阳之助，故「吉」。</p><p>上九：击蒙，不利为寇，利御寇。上九乃蒙极而怙终者也，其罪当击，故曰「击蒙」。「为」，当，依王晦叔作去声，与论语「为卫君乎」之「为」同。「寇」，指六三坎体之盗。上九而下与之应，则不利，处乎上而拒之，则利，故曰「不利为寇，利御寇」。䷄ 乾下坎上</p><p>「需」，有孚，光亨，贞吉，利涉大川。</p><p>「需」，待也。乾健而遇坎险，则未能上进，「需」之义也。「需」以五为成卦之主爻。「有孚，光亨，贞吉」，皆指五。「孚」，信也。九五与九二同德相信，是为「有孚」。阳明而光，故「亨」。固守以正而不妄动，故「吉」。坎水之险在前，「乾」以刚健临之，而又能「需」，则不至乎陷溺，故其象占为「利涉大川」。</p><p>初九：需于郊，利用恒，无咎。</p><p>尔雅云：「邑外谓之郊。」「郊」乃近邑之地也。易以中爻为邑，初、上为郊，初近二，故言「郊」。「恒」，久也。「需于郊」，虽去坎水远，亦不宜轻动，故其占为「利用恒」，然后可以「无咎」。</p><p>九二，需于沙，小有言，终吉。「沙」与「泥」相连，则稍近坎水之险矣。「需」于此，虽小有言语之相侵，然九二刚而得中，不急于进，故亦「终吉」。</p><p>九三，需于泥，致寇至。</p><p>「泥比沙」，则逼于坎水之险矣。九三过刚不中，非能「需」者也，故「致寇至」。</p><p>六四，需于血，出自穴。</p><p>「血」，伤也。三阳自下而进，四当避之，「需」于此而不避，必见伤矣。六四纯乎柔顺者也，故能释位而去，以听三阳之进，则彼自来，我自出，两无伤也。「穴」，乃阴虚之地，六四阴爻之虚，故言「穴」。</p><p>九五，需于酒食，贞吉。</p><p>「酒食」者，需客之具，所以待三阳之来也。唯能固守以正而不乱，则吉，故曰：「需于酒食，贞吉。」五为「需」主，故以彖辞「贞吉」属之。</p><p>上六，入于穴，有不速之客三人来，敬之，终吉。</p><p>上六「需」极，故不言「需」。阴爻之虚，故其象亦为「穴」。倒转为「讼」，则穴在下，故曰「入于穴」。三阳皆进而在上，非己所召，有不速之客三人来之象。诗伐木云：「以速诸父。」郑玄云：「速，召也。」「需」既极矣，故三客不待召而自来。柔不可以敌刚，寡不可以敌众，故戒之曰：「敬之终吉。」周易集说卷一，</p>',64)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
